  {w:"confine",ph:"kənˈfaɪn",pos:"v.",cn:"限制；禁闭",ex:"The discussion was confined to a narrow set of questions.",exCn:"讨论被限制在一小类问题上。",tag:"高频",note:"confine A to B；be confined to"},
  {w:"confirm",ph:"kənˈfɜːm",pos:"v.",cn:"证实；确认",ex:"The results confirm earlier findings from smaller studies.",exCn:"这些结果证实了此前小型研究的发现。",tag:"高频",note:"confirm that；confirmation 确认"},
  {w:"conflict",ph:"ˈkɒnflɪkt",pos:"n./v.",cn:"冲突；矛盾",ex:"The findings conflict with the official account.",exCn:"这些发现与官方说法相矛盾。",tag:"高频",note:"conflict with；in conflict；conflicting 相互矛盾的"},
  {w:"conform",ph:"kənˈfɔːm",pos:"v.",cn:"遵守；符合；从众",ex:"Teenagers often feel pressure to conform to group norms.",exCn:"青少年常常感到要遵从群体规范的压力。",tag:"高频",note:"conform to；conformity 从众"},
  {w:"confront",ph:"kənˈfrʌnt",pos:"v.",cn:"面对；对抗",ex:"The city is confronting a serious housing shortage.",exCn:"这座城市正面临严重的住房短缺。",tag:"高频",note:"be confronted with；confront a problem；confrontation 对抗"},
  {w:"consensus",ph:"kənˈsensəs",pos:"n.",cn:"共识；一致意见",ex:"There is a broad consensus that the current system is unfair.",exCn:"人们普遍认为现行制度不公平。",tag:"高频",note:"consensus on / about；reach a consensus"},
  {w:"consequence",ph:"ˈkɒnsɪkwəns",pos:"n.",cn:"结果；后果；重要性",ex:"As a consequence, many families were left without coverage.",exCn:"结果，许多家庭失去了保障。",tag:"高频",note:"as a consequence of；consequent 随之发生的"},
  {w:"conservative",ph:"kənˈsɜːvətɪv",pos:"a./n.",cn:"保守的；保守者",ex:"The estimate is conservative; the true cost is likely higher.",exCn:"这一估计偏保守，真实成本可能更高。",tag:"高频",note:"conservative estimate；conserve 保护"},
  {w:"considerable",ph:"kənˈsɪdərəbl",pos:"a.",cn:"相当大的；可观的",ex:"The project required considerable time and money.",exCn:"这个项目需要大量时间和金钱。",tag:"高频",note:"considerable 大量的；considerate 体贴的"},
  {w:"consist",ph:"kənˈsɪst",pos:"v.",cn:"由…组成；在于",ex:"The course consists of twelve lectures and four seminars.",exCn:"这门课由十二次讲座和四次研讨组成。",tag:"高频",note:"consist of；consist in 在于；consistent 一致的"},
  {w:"constant",ph:"ˈkɒnstənt",pos:"a.",cn:"不断的；恒定的",ex:"The constant noise made concentration impossible.",exCn:"持续的噪音让人无法集中注意力。",tag:"高频",note:"constant 持续不断的；constantly 不断地"},
  {w:"constitute",ph:"ˈkɒnstɪtjuːt",pos:"v.",cn:"构成；组成；设立",ex:"Women constitute nearly half of the workforce.",exCn:"女性占劳动力的近一半。",tag:"高频",note:"constitute 构成；constitution 宪法/体质"},
  {w:"constraint",ph:"kənˈstreɪnt",pos:"n.",cn:"限制；约束",ex:"Time constraints prevented a full investigation.",exCn:"时间限制使全面调查无法进行。",tag:"高频",note:"constraint on；constrain 限制"},
  {w:"consume",ph:"kənˈsjuːm",pos:"v.",cn:"消耗；消费",ex:"Households consume far more energy in winter.",exCn:"家庭在冬天消耗的能源要多得多。",tag:"高频",note:"consume energy；consumer 消费者；consumption 消费"},
  {w:"contemporary",ph:"kənˈtemprəri",pos:"a./n.",cn:"当代的；同时代的",ex:"The novel speaks to contemporary anxieties about technology.",exCn:"这部小说回应了当代人对技术的焦虑。",tag:"高频",note:"contemporary 当代的；contemporary with 与…同时代"},
  {w:"contend",ph:"kənˈtend",pos:"v.",cn:"主张；竞争；应付",ex:"Critics contend that the reform will hurt the poorest.",exCn:"批评者主张，这项改革将伤害最贫困的人。",tag:"高频",note:"contend that；contend with 应对；contention 争论"},
  {w:"context",ph:"ˈkɒntekst",pos:"n.",cn:"语境；背景",ex:"The remark makes sense only in its historical context.",exCn:"这句话只有放在历史背景中才说得通。",tag:"高频",note:"in the context of；out of context 断章取义"},
  {w:"contradict",ph:"ˌkɒntrəˈdɪkt",pos:"v.",cn:"反驳；与…矛盾",ex:"The latest data contradict the earlier report.",exCn:"最新数据与早先的报告相矛盾。",tag:"高频",note:"contradict 直接跟宾语；contradiction 矛盾"},
  {w:"contrast",ph:"ˈkɒntrɑːst",pos:"n./v.",cn:"对比；反差",ex:"In contrast to previous studies, this one finds no effect.",exCn:"与以往研究不同，这项研究没有发现任何效果。",tag:"高频",note:"in contrast to；contrast A with B；by contrast"},
  {w:"contribute",ph:"kənˈtrɪbjuːt",pos:"v.",cn:"促成；贡献；投稿",ex:"Several factors contributed to the decline in sales.",exCn:"多个因素促成了销量下降。",tag:"高频",note:"contribute to；contribution 贡献"},
  {w:"controversial",ph:"ˌkɒntrəˈvɜːʃl",pos:"a.",cn:"有争议的",ex:"The decision proved deeply controversial.",exCn:"这一决定引发了很大争议。",tag:"高频",note:"controversial issue；controversy 争议"},
  {w:"convention",ph:"kənˈvenʃn",pos:"n.",cn:"惯例；大会；公约",ex:"The novel challenges the conventions of the genre.",exCn:"这部小说挑战了该体裁的惯例。",tag:"高频",note:"social conventions；conventional 传统的"},
  {w:"convert",ph:"kənˈvɜːt",pos:"v.",cn:"转变；转换；改装",ex:"The old factory was converted into apartments.",exCn:"这座旧工厂被改造成了公寓。",tag:"高频",note:"convert A into B；conversion 转变"},
  {w:"convey",ph:"kənˈveɪ",pos:"v.",cn:"传达；运送",ex:"The chart conveys little information about causes.",exCn:"这张图表几乎没有传达关于原因的信息。",tag:"高频",note:"convey a message；convey 传达/运输"},
  {w:"convince",ph:"kənˈvɪns",pos:"v.",cn:"说服；使确信",ex:"The evidence convinced even the skeptics.",exCn:"这些证据连怀疑者都说服了。",tag:"核心",note:"convince sb of sth；convincing 有说服力的"},
  {w:"credible",ph:"ˈkredəbl",pos:"a.",cn:"可信的；可靠的",ex:"We need a credible explanation for the gap.",exCn:"我们需要一个可信的解释来说明这一差距。",tag:"核心",note:"credible source；credibility 可信度"},
  {w:"crisis",ph:"ˈkraɪsɪs",pos:"n.",cn:"危机；紧要关头",ex:"The housing crisis has been decades in the making.",exCn:"住房危机是几十年间逐渐形成的。",tag:"核心",note:"复数 crises；a crisis of confidence"},
  {w:"criterion",ph:"kraɪˈtɪəriən",pos:"n.",cn:"标准；准则",ex:"Cost is only one criterion for judging the policy.",exCn:"成本只是评判该政策的一项标准。",tag:"核心",note:"复数 criteria；criterion for"},
  {w:"crucial",ph:"ˈkruːʃl",pos:"a.",cn:"至关重要的",ex:"Early support is crucial to a child's development.",exCn:"早期支持对儿童发展至关重要。",tag:"核心",note:"be crucial to / for"},
  {w:"cultivate",ph:"ˈkʌltɪveɪt",pos:"v.",cn:"培养；耕种",ex:"Schools should cultivate curiosity rather than obedience.",exCn:"学校应培养好奇心，而不是服从。",tag:"核心",note:"cultivate a habit；cultivation 培养"},
  {w:"decline",ph:"dɪˈklaɪn",pos:"v./n.",cn:"下降；拒绝；衰退",ex:"Enrollment has declined steadily since 2015.",exCn:"自2015年以来，入学人数稳步下降。",tag:"核心",note:"decline to do 拒绝；on the decline 在衰退"},
  {w:"dedicate",ph:"ˈdedɪkeɪt",pos:"v.",cn:"致力于；奉献",ex:"She dedicated her career to studying urban poverty.",exCn:"她把职业生涯献给了城市贫困研究。",tag:"核心",note:"dedicate oneself to；dedicated 专注的"},
  {w:"defect",ph:"ˈdiːfekt",pos:"n./v.",cn:"缺陷；叛逃",ex:"The study has a serious methodological defect.",exCn:"这项研究存在严重的方法缺陷。",tag:"核心",note:"defective 有缺陷的；defection 叛逃"},
  {w:"define",ph:"dɪˈfaɪn",pos:"v.",cn:"定义；界定",ex:"Success is defined differently in different cultures.",exCn:"不同文化对成功的定义不同。",tag:"核心",note:"define A as B；definition 定义"},
  {w:"deliberate",ph:"dɪˈlɪbərət",pos:"a./v.",cn:"故意的；从容的；仔细考虑",ex:"The omission appears to have been deliberate.",exCn:"这一遗漏似乎是故意的。",tag:"核心",note:"deliberate on 仔细考虑；deliberately 故意地"},
  {w:"demonstrate",ph:"ˈdemənstreɪt",pos:"v.",cn:"证明；展示；示威",ex:"The experiment demonstrates how quickly habits form.",exCn:"实验展示了习惯形成之快。",tag:"核心",note:"demonstrate that；demonstration 演示/示威"},
  {w:"deny",ph:"dɪˈnaɪ",pos:"v.",cn:"否认；剥夺",ex:"The company denied that it had misled investors.",exCn:"公司否认曾误导投资者。",tag:"核心",note:"deny doing sth；deny sb sth；denial 否认"},
  {w:"derive",ph:"dɪˈraɪv",pos:"v.",cn:"源于；获得",ex:"The word derives from an old French term.",exCn:"这个词源自一个古法语词。",tag:"核心",note:"derive from；derive A from B；derivative 衍生物"},
  {w:"deserve",ph:"dɪˈzɜːv",pos:"v.",cn:"值得；应得",ex:"The issue deserves more attention than it receives.",exCn:"这个问题值得比现在更多的关注。",tag:"核心",note:"deserve to do；deserve attention"},
  {w:"detect",ph:"dɪˈtekt",pos:"v.",cn:"察觉；探测",ex:"The sensors can detect tiny changes in temperature.",exCn:"传感器能探测到温度的微小变化。",tag:"核心",note:"detect 察觉；detection 侦查"},
  {w:"deter",ph:"dɪˈtɜː(r)",pos:"v.",cn:"阻止；威慑",ex:"Higher fines may deter some people from cheating.",exCn:"提高罚款或许能阻止一些人作弊。",tag:"核心",note:"deter sb from doing；deterrent 威慑物"},
  {w:"determine",ph:"dɪˈtɜːmɪn",pos:"v.",cn:"决定；查明；下决心",ex:"The outcome will be determined by turnout.",exCn:"结果将由投票率决定。",tag:"核心",note:"determine to do；be determined to；determination 决心"},
  {w:"diminish",ph:"dɪˈmɪnɪʃ",pos:"v.",cn:"减少；削弱",ex:"The importance of handwriting has diminished over time.",exCn:"书写的重要性随着时间推移而下降。",tag:"核心",note:"diminishing returns 收益递减"},
  {w:"discard",ph:"dɪsˈkɑːd",pos:"v.",cn:"抛弃；丢弃",ex:"Consumers discard millions of phones every year.",exCn:"消费者每年丢弃数百万部手机。",tag:"核心",note:"discard an idea；discard 指丢弃不再需要之物"},
  {w:"discipline",ph:"ˈdɪsəplɪn",pos:"n./v.",cn:"学科；纪律；训练",ex:"Economics is a discipline that prizes clear models.",exCn:"经济学是一门重视清晰模型的学科。",tag:"核心",note:"academic discipline；self-discipline；disciplinary 纪律的"},
  {w:"disclose",ph:"dɪsˈkləʊz",pos:"v.",cn:"披露；透露",ex:"Companies are required to disclose their emissions.",exCn:"公司被要求披露其排放量。",tag:"核心",note:"disclose sth to sb；disclosure 披露"},
  {w:"discriminate",ph:"dɪˈskrɪmɪneɪt",pos:"v.",cn:"歧视；区分",ex:"The algorithm appears to discriminate against older applicants.",exCn:"该算法似乎歧视年龄较大的申请者。",tag:"核心",note:"discriminate against；discriminate between；discrimination 歧视"},
  {w:"dispute",ph:"dɪˈspjuːt",pos:"n./v.",cn:"争论；争执",ex:"The two sides dispute the meaning of the contract.",exCn:"双方对合同含义存在争议。",tag:"核心",note:"in dispute；disputed 有争议的"},
  {w:"distinct",ph:"dɪˈstɪŋkt",pos:"a.",cn:"不同的；清晰的",ex:"There are two distinct explanations for the pattern.",exCn:"对这一模式有两种截然不同的解释。",tag:"核心",note:"be distinct from；distinction 区别"},
  {w:"distinguish",ph:"dɪˈstɪŋɡwɪʃ",pos:"v.",cn:"区分；辨别；使杰出",ex:"It is hard to distinguish cause from correlation.",exCn:"很难把因果与相关区分开来。",tag:"核心",note:"distinguish between A and B；distinguish A from B"},
  {w:"distort",ph:"dɪˈstɔːt",pos:"v.",cn:"扭曲；歪曲",ex:"Selective reporting distorts the public's understanding.",exCn:"选择性报道扭曲了公众的理解。",tag:"核心",note:"distort the truth；distortion 歪曲"},
  {w:"diverse",ph:"daɪˈvɜːs",pos:"a.",cn:"多样的；不同的",ex:"The city has a remarkably diverse population.",exCn:"这座城市的人口构成非常多元。",tag:"核心",note:"diverse 多样的；diversity 多样性"},
  {w:"domestic",ph:"dəˈmestɪk",pos:"a.",cn:"国内的；家庭的",ex:"Domestic demand has weakened since the spring.",exCn:"自春季以来，国内需求走弱。",tag:"核心",note:"domestic market；domestic violence；domesticate 驯化"},
  {w:"dominate",ph:"ˈdɒmɪneɪt",pos:"v.",cn:"支配；主导；俯视",ex:"A few platforms dominate the market for online reviews.",exCn:"少数平台主导了在线评论市场。",tag:"核心",note:"dominate the market；dominant 主导的"},
  {w:"dramatic",ph:"drəˈmætɪk",pos:"a.",cn:"显著的；戏剧性的",ex:"There has been a dramatic shift in public opinion.",exCn:"公众舆论发生了显著转变。",tag:"核心",note:"dramatic increase；drama 戏剧"},
  {w:"dynamic",ph:"daɪˈnæmɪk",pos:"a./n.",cn:"动态的；有活力的；动力",ex:"The labor market is more dynamic than the figures suggest.",exCn:"劳动力市场比数据显示的更有活力。",tag:"核心",note:"dynamics 动态/力学"},
  {w:"eliminate",ph:"ɪˈlɪmɪneɪt",pos:"v.",cn:"消除；淘汰",ex:"The new design eliminates the need for a second cable.",exCn:"新设计免去了第二根线缆的需要。",tag:"核心",note:"eliminate the need for；elimination 消除"},
  {w:"emerge",ph:"ɪˈmɜːdʒ",pos:"v.",cn:"出现；浮现；显露",ex:"A clearer picture emerged only after several years.",exCn:"几年之后才浮现出更清晰的图景。",tag:"核心",note:"emerge from；emergence 出现；emerging 新兴的"},
  {w:"emphasis",ph:"ˈemfəsɪs",pos:"n.",cn:"强调；重点",ex:"The report places emphasis on prevention rather than punishment.",exCn:"报告强调预防而非惩罚。",tag:"核心",note:"place / put emphasis on；emphasize 强调"},
  {w:"empirical",ph:"ɪmˈpɪrɪkl",pos:"a.",cn:"经验的；实证的",ex:"The claim is plausible but lacks empirical support.",exCn:"这一说法看似合理，但缺乏实证支持。",tag:"核心",note:"empirical evidence；empirically 经验上"},
  {w:"enable",ph:"ɪˈneɪbl",pos:"v.",cn:"使能够；使成为可能",ex:"Cheap sensors enable researchers to collect data at scale.",exCn:"廉价传感器使研究者能够大规模收集数据。",tag:"核心",note:"enable sb to do；enable 不接 doing"},
  {w:"encounter",ph:"ɪnˈkaʊntə(r)",pos:"v./n.",cn:"遭遇；偶遇",ex:"Travelers encountered long delays at the border.",exCn:"旅客在边境遭遇长时间延误。",tag:"核心",note:"encounter problems；encounter 较正式"},
  {w:"endure",ph:"ɪnˈdjʊə(r)",pos:"v.",cn:"忍受；持续",ex:"The community endured years of neglect.",exCn:"这个社区多年遭受忽视。",tag:"核心",note:"endure 忍受/持久；endurance 忍耐力"},
  {w:"enforce",ph:"ɪnˈfɔːs",pos:"v.",cn:"执行；强制实施",ex:"The rules are difficult to enforce in practice.",exCn:"这些规则在实践中难以执行。",tag:"核心",note:"enforce a law；enforcement 执法"},
  {w:"enhance",ph:"ɪnˈhɑːns",pos:"v.",cn:"提高；增强",ex:"Good lighting can enhance the sense of safety.",exCn:"良好的照明能增强安全感。",tag:"核心",note:"enhance 提升（质量/价值）；enhancement 提升"},
  {w:"enormous",ph:"ɪˈnɔːməs",pos:"a.",cn:"巨大的；庞大的",ex:"The project has attracted enormous public interest.",exCn:"该项目吸引了极大的公众兴趣。",tag:"核心",note:"enormous 巨大的；enormously 非常"},
  {w:"ensure",ph:"ɪnˈʃʊə(r)",pos:"v.",cn:"确保；保证",ex:"Checks are in place to ensure that data is accurate.",exCn:"已有检查措施确保数据准确。",tag:"核心",note:"ensure that；ensure 确保，区别于 assure 使某人放心"},
  {w:"entail",ph:"ɪnˈteɪl",pos:"v.",cn:"需要；涉及；使必要",ex:"Reform would entail significant short-term costs.",exCn:"改革将带来可观的短期成本。",tag:"核心",note:"entail doing sth；entail 不用于被动"},
  {w:"enterprise",ph:"ˈentəpraɪz",pos:"n.",cn:"企业；事业；进取心",ex:"Small enterprises create most new jobs.",exCn:"小企业创造了大多数新就业岗位。",tag:"核心",note:"private enterprise；enterprising 有进取心的"},
  {w:"entitle",ph:"ɪnˈtaɪtl",pos:"v.",cn:"使有权；给…命名",ex:"The law entitles workers to paid leave.",exCn:"法律赋予劳动者带薪休假的权利。",tag:"核心",note:"entitle sb to sth；be entitled to 有权"},
  {w:"equivalent",ph:"ɪˈkwɪvələnt",pos:"a./n.",cn:"等同的；等价物",ex:"The two qualifications are not equivalent.",exCn:"这两种资质并不等同。",tag:"核心",note:"be equivalent to；equivalence 等价"},
  {w:"essential",ph:"ɪˈsenʃl",pos:"a./n.",cn:"必要的；本质的；要素",ex:"Access to clean water is essential for public health.",exCn:"获得清洁用水对公共健康至关重要。",tag:"核心",note:"be essential to / for；essentially 本质上"},
  {w:"establish",ph:"ɪˈstæblɪʃ",pos:"v.",cn:"建立；证实；确立",ex:"The study establishes a link between sleep and memory.",exCn:"这项研究证实了睡眠与记忆之间的联系。",tag:"核心",note:"establish a link；establishment 建立/机构"},
  {w:"estimate",ph:"ˈestɪmeɪt",pos:"v./n.",cn:"估计；估价",ex:"Officials estimate that the repairs will take a year.",exCn:"官员估计维修需要一年。",tag:"核心",note:"estimate that；a rough estimate；estimation 判断"},
  {w:"ethical",ph:"ˈeθɪkl",pos:"a.",cn:"伦理的；合乎道德的",ex:"The experiment raised serious ethical questions.",exCn:"这项实验引发了严重的伦理问题。",tag:"核心",note:"ethical concerns；ethics 伦理"},
  {w:"evaluate",ph:"ɪˈvæljueɪt",pos:"v.",cn:"评估；评价",ex:"The program will be evaluated after two years.",exCn:"该项目将在两年后接受评估。",tag:"核心",note:"evaluate 评估；evaluation 评价"},
  {w:"evident",ph:"ˈevɪdənt",pos:"a.",cn:"明显的；显然的",ex:"It is evident from the data that the trend has reversed.",exCn:"数据清楚表明趋势已经逆转。",tag:"核心",note:"It is evident that；evidence 证据"},
  {w:"evolve",ph:"ɪˈvɒlv",pos:"v.",cn:"演变；进化；逐步发展",ex:"Language evolves faster than dictionaries can record.",exCn:"语言演变的速度快于词典记录的速度。",tag:"核心",note:"evolve into；evolution 进化"},
  {w:"exaggerate",ph:"ɪɡˈzædʒəreɪt",pos:"v.",cn:"夸大；夸张",ex:"The media tend to exaggerate the risks.",exCn:"媒体往往夸大风险。",tag:"核心",note:"exaggerate 夸大；exaggeration 夸张"},
  {w:"exceed",ph:"ɪkˈsiːd",pos:"v.",cn:"超过；超越",ex:"Demand far exceeded the available supply.",exCn:"需求远远超过可用供给。",tag:"核心",note:"exceed 超过；excess 过量；excessive 过度的"},
  {w:"excessive",ph:"ɪkˈsesɪv",pos:"a.",cn:"过度的；过分的",ex:"Excessive screen time may harm sleep.",exCn:"过长的屏幕使用时间可能损害睡眠。",tag:"核心",note:"excessive 贬义；excessively 过度地"},
  {w:"exclude",ph:"ɪkˈskluːd",pos:"v.",cn:"排除；不包括",ex:"The sample excludes part-time workers.",exCn:"该样本不包括兼职工作者。",tag:"核心",note:"exclude sb from；exclusion 排斥"},
  {w:"exhibit",ph:"ɪɡˈzɪbɪt",pos:"v./n.",cn:"表现出；展出；展品",ex:"The study exhibits several weaknesses.",exCn:"这项研究暴露出若干弱点。",tag:"核心",note:"exhibit 表现出；exhibition 展览"},
  {w:"expand",ph:"ɪkˈspænd",pos:"v.",cn:"扩大；扩展；详述",ex:"The program has expanded to cover 200 schools.",exCn:"该项目已扩展到两百所学校。",tag:"核心",note:"expand into；expand on 详述；expansion 扩张"},
  {w:"explicit",ph:"ɪkˈsplɪsɪt",pos:"a.",cn:"明确的；直白的",ex:"The contract makes no explicit mention of overtime.",exCn:"合同没有明确提到加班。",tag:"核心",note:"explicit 明确的；implicit 含蓄的"},
  {w:"exploit",ph:"ɪkˈsplɔɪt",pos:"v./n.",cn:"利用；剥削；功绩",ex:"Companies exploit gaps in the regulations.",exCn:"公司利用监管漏洞。",tag:"核心",note:"exploit resources；exploitation 剥削/开发"},
  {w:"expose",ph:"ɪkˈspəʊz",pos:"v.",cn:"揭露；使接触",ex:"The report exposed widespread fraud.",exCn:"这份报告揭露了广泛的欺诈行为。",tag:"核心",note:"expose sb to sth；be exposed to；exposure 暴露"},
  {w:"extend",ph:"ɪkˈstend",pos:"v.",cn:"延长；扩展；给予",ex:"The deadline has been extended by two weeks.",exCn:"截止日期已延长两周。",tag:"核心",note:"extend to；extend an invitation；extension 延长"},
  {w:"external",ph:"ɪkˈstɜːnl",pos:"a.",cn:"外部的；外来的",ex:"The project depends on external funding.",exCn:"该项目依赖外部资金。",tag:"核心",note:"external pressure；反义 internal"},
  {w:"extract",ph:"ɪkˈstrækt",pos:"v./n.",cn:"提取；摘录",ex:"The researchers extracted DNA from the samples.",exCn:"研究者从样本中提取了DNA。",tag:"核心",note:"extract A from B；extraction 提取"},
  {w:"facilitate",ph:"fəˈsɪlɪteɪt",pos:"v.",cn:"促进；使便利",ex:"The new software facilitates collaboration across teams.",exCn:"新软件促进了跨团队协作。",tag:"核心",note:"facilitate 促进，不接 to do；facilitation 便利"},
  {w:"feasible",ph:"ˈfiːzəbl",pos:"a.",cn:"可行的；行得通的",ex:"It is not feasible to test every student.",exCn:"对每个学生都进行测试并不可行。",tag:"核心",note:"feasible 可行的；feasibility 可行性"},
  {w:"flexible",ph:"ˈfleksəbl",pos:"a.",cn:"灵活的；可弯曲的",ex:"Flexible working hours appeal to parents.",exCn:"弹性工作时间对父母有吸引力。",tag:"核心",note:"flexible 灵活的；flexibility 灵活性"},
  {w:"fluctuate",ph:"ˈflʌktʃueɪt",pos:"v.",cn:"波动；起伏",ex:"Oil prices have fluctuated wildly this year.",exCn:"今年油价剧烈波动。",tag:"核心",note:"fluctuate between；fluctuation 波动"},
  {w:"foster",ph:"ˈfɒstə(r)",pos:"v.",cn:"培养；促进；寄养",ex:"Mentoring can foster a sense of belonging.",exCn:"导师制能培养归属感。",tag:"核心",note:"foster 培养；foster care 寄养"},
  {w:"framework",ph:"ˈfreɪmwɜːk",pos:"n.",cn:"框架；体系",ex:"The report provides a framework for assessing risk.",exCn:"报告提供了一个评估风险的框架。",tag:"核心",note:"within the framework of；conceptual framework"},
  {w:"fundamental",ph:"ˌfʌndəˈmentl",pos:"a./n.",cn:"根本的；基本的；基础",ex:"Trust is fundamental to any exchange.",exCn:"信任是一切交换的基础。",tag:"核心",note:"be fundamental to；fundamentally 根本上"},
  {w:"generate",ph:"ˈdʒenəreɪt",pos:"v.",cn:"产生；发电",ex:"The plant generates enough power for 20,000 homes.",exCn:"这座电厂发的电足够两万户家庭使用。",tag:"核心",note:"generate electricity / interest；generation 一代/产生"},
  {w:"genuine",ph:"ˈdʒenjuɪn",pos:"a.",cn:"真正的；真诚的",ex:"There is genuine disagreement among experts.",exCn:"专家之间存在真正的分歧。",tag:"核心",note:"genuine 真正的；genuinely 真诚地"},
  {w:"guarantee",ph:"ˌɡærənˈtiː",pos:"v./n.",cn:"保证；担保",ex:"The policy does not guarantee a job.",exCn:"该政策并不保证一份工作。",tag:"核心",note:"guarantee sb sth；guarantee to do；under guarantee 在保修期内"},
  {w:"highlight",ph:"ˈhaɪlaɪt",pos:"v./n.",cn:"强调；突出；亮点",ex:"The survey highlights the gap between rich and poor schools.",exCn:"调查突显了富裕学校与贫困学校之间的差距。",tag:"核心",note:"highlight 强调；highlight 作名词指亮点"},
  {w:"hypothesis",ph:"haɪˈpɒθəsɪs",pos:"n.",cn:"假设；假说",ex:"The hypothesis was tested in a controlled experiment.",exCn:"这一假设在对照实验中得到了检验。",tag:"核心",note:"复数 hypotheses；test a hypothesis"},
  {w:"identify",ph:"aɪˈdentɪfaɪ",pos:"v.",cn:"识别；确认；认同",ex:"The study identifies three factors behind the trend.",exCn:"研究确认了这一趋势背后的三个因素。",tag:"核心",note:"identify A as B；identify with 认同；identity 身份"},
  {w:"ignore",ph:"ɪɡˈnɔː(r)",pos:"v.",cn:"忽视；不理会",ex:"Policymakers ignored the warning signs.",exCn:"政策制定者忽视了警示信号。",tag:"核心",note:"ignore 故意忽视；ignorance 无知"}
