    point: "两个过去分词短语分别修饰两个分句；however 是插入副词，不连接句子，分号才是连接手段。",
    cn: "单独看，这些数字显示稳步下降；但与其他行业的数据并列，它们揭示的却是一种远非罕见的模式。"
