      point: "主语后插入让步状语，谓语被推到最后。先跳过 however 插入语抓主干；however + 副词表示“无论多么……”。",
      cn: "读者会为高质量新闻付费——这一假设无论被重复多少次，都未得到那些已习惯免费内容的受众行为的支持。"
