        "A field of wheat looks like a single crop, but it is also a genetic decision. Modern varieties are bred for uniformity: the same height, the same ripening date, the same response to fertilizer. Uniformity makes harvesting and processing efficient. It also means that a field is, in genetic terms, one large target.",
