        "In many cities, the rules that govern housing are drawn so that only two kinds of building are easy to permit: the detached house and the large apartment block. The duplex, the row house, the small building with a shop on the ground floor and flats above—the kinds of housing that once filled the space between—are often illegal to build, even where they already stand.",
